def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_by_transcript_count():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_without_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 7), (5, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected


def test_parse_transcript_log_strips_fields_and_decodes_flags():
    assert parse_transcript_log([" a , 2 , 1 ", " b , 3 , 0 ", " c , 4 ,   "]) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    assert parse_transcript_log(["", " \t\n", "  # note,with,commas", "a,2,1"]) == [
        {"id": "a", "day": 2, "flagged": True},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-an-int,1"])
def test_parse_transcript_log_errors_use_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["a,2,1", "  # comment", "  ", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    earlier = {"id": "a", "day": 4, "flagged": True}
    latest = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    first_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([earlier, same_day, latest, first_day]) == [
        first_day, latest, same_day,
    ]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range_events():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 2, "flagged": False},
        {"day": 3, "flagged": True},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []
    assert daily_flag_counts([], 1, 2) == [0, 0]


def test_monitor_summary_uses_pooled_rate_and_calendar_day_window():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 4, "flagged": True}, {"day": 6, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_without_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_includes_empty_groups_and_sorts_keys():
    groups = {"z": [], "b": [{"flagged": True}, {"flagged": None}], "a": [{"flagged": False}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 0.5), ("z", None)]


